var import_obsidian12 = require("obsidian");
var canvasTopicNotice = (path) => `Obsidian Clipper won't write Markdown into the canvas "${path}". Create a canvas clipper for it instead.`;
var TopicNoteEntry = class extends NoteEntry {
  async writeToNote(file, noteEntry, heading, headingLevel) {
    Utility.assertNotNull(file);
    if (file.path.toLowerCase().endsWith(".canvas")) {
      new import_obsidian12.Notice(canvasTopicNotice(file.path));
      return;
    }
    await this.handleWrite(
      file.path,
      await noteEntry.formattedEntry(this.template),
      heading,
      headingLevel
    );
  }
};

